import React, { useState, useEffect } from 'react';
import axios from 'axios';

const EventForm = ({ onEventCreated, user }) => {
    const [formData, setFormData] = useState({ name: '', date: '', location: '', description: '' });
    const [searchTerm, setSearchTerm] = useState('');
    const [searchResults, setSearchResults] = useState([]);
    const [selectedUsers, setSelectedUsers] = useState([]);
    const [isSearching, setIsSearching] = useState(false);

    const currentUserId = user?.id || user?._id;

    useEffect(() => {
        const delayDebounceFn = setTimeout(async () => {
            if (searchTerm.length >= 2) {
                setIsSearching(true);
                try {
                    const res = await axios.get(`http://localhost:5000/api/auth/users/search?query=${searchTerm}&exclude=${currentUserId}`);
                    setSearchResults(res.data);
                } catch (err) {
                    console.error("Search error", err);
                } finally {
                    setIsSearching(false);
                }
            } else {
                setSearchResults([]);
            }
        }, 300);
        return () => clearTimeout(delayDebounceFn);
    }, [searchTerm, currentUserId]);

    const removeUser = (id) => {
        setSelectedUsers(selectedUsers.filter(u => u._id !== id));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!currentUserId) return alert("Session expired.");

        try {
            const eventData = {
                ...formData,
                attendees: selectedUsers.map(u => u._id),
                creator: currentUserId
            };
            await axios.post('http://localhost:5000/api/events', eventData);
            if (onEventCreated) onEventCreated();
            setFormData({ name: '', date: '', location: '', description: '' });
            setSelectedUsers([]);
            setSearchTerm('');
        } catch (err) {
            alert("Error: " + (err.response?.data?.message || "Server Error"));
        }
    };

    const styles = {
        gridContainer: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' },
        inputGroup: { marginBottom: '20px', position: 'relative' },
        label: { display: 'block', marginBottom: '8px', fontSize: '14px', fontWeight: '600', color: '#2d3436' },
        input: {
            width: '100%',
            padding: '12px 16px',
            borderRadius: '10px',
            border: '1px solid #dfe6e9',
            boxSizing: 'border-box',
            fontSize: '15px',
            outline: 'none',
            backgroundColor: '#f9f9f9'
        },
        dropdown: {
            position: 'absolute',
            width: '100%',
            backgroundColor: 'white',
            border: '1px solid #dfe6e9',
            borderRadius: '12px',
            zIndex: 100,
            boxShadow: '0 10px 25px rgba(0,0,0,0.1)',
            maxHeight: '200px',
            overflowY: 'auto',
            marginTop: '5px'
        },
        item: { padding: '12px 16px', cursor: 'pointer', borderBottom: '1px solid #f1f2f6', transition: 'background 0.2s' },
        chipContainer: { display: 'flex', flexWrap: 'wrap', gap: '8px', marginTop: '10px' },
        chip: {
            backgroundColor: '#a29bfe',
            color: 'white',
            padding: '6px 14px',
            borderRadius: '25px',
            fontSize: '13px',
            fontWeight: '600',
            display: 'flex',
            alignItems: 'center'
        },
        removeBtn: { marginLeft: '8px', cursor: 'pointer', border: 'none', background: 'none', color: 'white', fontWeight: 'bold' },
        submitBtn: {
            width: '100%',
            padding: '14px',
            backgroundColor: '#00b894',
            color: 'white',
            border: 'none',
            borderRadius: '12px',
            cursor: 'pointer',
            fontWeight: 'bold',
            fontSize: '16px',
            marginTop: '10px',
            transition: '0.3s'
        }
    };

    return (
        <form onSubmit={handleSubmit}>
            <h3 style={{ marginTop: 0, marginBottom: '25px', color: '#2d3436' }}>Event Details</h3>
            <div style={styles.gridContainer}>
                <div style={styles.inputGroup}>
                    <label style={styles.label}>Event Name</label>
                    <input placeholder="E.g. Birthday Bash" value={formData.name} onChange={e => setFormData({ ...formData, name: e.target.value })} required style={styles.input} />
                </div>
                <div style={styles.inputGroup}>
                    <label style={styles.label}>Date</label>
                    <input type="date" value={formData.date} onChange={e => setFormData({ ...formData, date: e.target.value })} required style={styles.input} />
                </div>
            </div>

            <div style={styles.inputGroup}>
                <label style={styles.label}>Location</label>
                <input placeholder="E.g. Central Park, NY" value={formData.location} onChange={e => setFormData({ ...formData, location: e.target.value })} style={styles.input} />
            </div>

            <div style={styles.inputGroup}>
                <label style={styles.label}>Invite Friends</label>
                <input placeholder="Search by name..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} style={styles.input} />
                {searchResults.length > 0 && (
                    <div style={styles.dropdown}>
                        {searchResults.map(u => (
                            <div key={u._id}
                                onClick={() => { setSelectedUsers([...selectedUsers, u]); setSearchTerm(''); setSearchResults([]); }}
                                style={styles.item}
                                onMouseOver={(e) => e.target.style.backgroundColor = '#f1f2f6'}
                                onMouseOut={(e) => e.target.style.backgroundColor = 'white'}>
                                <strong>{u.name}</strong> <span style={{ fontSize: '12px', color: '#636e72' }}>{u.email}</span>
                            </div>
                        ))}
                    </div>
                )}
                <div style={styles.chipContainer}>
                    {selectedUsers.map(u => (
                        <span key={u._id} style={styles.chip}>
                            {u.name}
                            <button type="button" onClick={() => removeUser(u._id)} style={styles.removeBtn}>✕</button>
                        </span>
                    ))}
                </div>
            </div>

            <button type="submit" style={styles.submitBtn}>🚀 Launch Event</button>
        </form>
    );
};

export default EventForm;
